def loads(data, wrapper=dict):

    if not isinstance(data, str):
        raise TypeError('can only load a str as an ACF but got ' + type(data).__name__)

    parsed = wrapper()
    current_section = parsed
    sections = []

    lines = (line.strip() for line in data.splitlines())

    for line in lines:
        try:
            key, value = line.split(None, 1)
            key = key.replace('"', '').lstrip()
            value = value.replace('"', '').rstrip()
        except ValueError:
            if line == SECTION_START:
                # Initialize the last added section.
                current_section = _prepare_subsection(parsed, sections, wrapper)
            elif line == SECTION_END:
                # Remove the last section from the queue.
                sections.pop()
            else:
                # Add a new section to the queue.
                sections.append(line.replace('"', ''))
            continue

        current_section[key] = value

    return parsed

def _prepare_subsection(data, sections, wrapper):

    current = data
    for i in sections[:-1]:
        current = current[i]

    current[sections[-1]] = wrapper()
    return current[sections[-1]]

def list_filenames_in_directory(self, dirname):

    prefix = self._create_prefix(dirname)
    filenames = []
    for obj in self._bucket.objects.filter(Prefix=prefix):
        if obj.key.endswith('/'):
            # a directory redirect object, not a file
            continue
        obj_dirname = os.path.dirname(obj.key)
        if obj_dirname == prefix:
            # object is at root of directory
            filenames.append(os.path.relpath(obj.key,
                                             start=prefix))
    return filenames

@classmethod
def from_object(cls: Type["Config"], instance: Union[object, str]) -> "Config":

    if isinstance(instance, str):
        try:
            path, config = instance.rsplit(".", 1)
        except ValueError:
            path = instance
            instance = importlib.import_module(instance)
        else:
            module = importlib.import_module(path)
            instance = getattr(module, config)

    mapping = {
        key: getattr(instance, key)
        for key in dir(instance)
        if not isinstance(getattr(instance, key), types.ModuleType)
    }
    return cls.from_mapping(mapping)

